//! Disposable chat peer for UI QA against a LOCAL server; never opens user data.
//! cargo run --example qa_peer -- <dir> <ws://127.0.0.1:8787/ws>
//! Publishes a profile, prints its chat code, approves and answers whoever writes.
//! With a third argument (a chat code) it sets an avatar and writes to that peer first.
use serde_json::{json, Value};
use std::sync::{mpsc::channel, Arc};
use valanium_core::{client::{Engine, EventSink}, command::Command};

fn main() -> Result<(), Box<dyn std::error::Error>> {
    let args: Vec<String> = std::env::args().collect();
    let dir = std::path::PathBuf::from(args.get(1).ok_or("directory required")?);
    let url = args.get(2).ok_or("server url required")?.clone();
    if !(url.starts_with("ws://127.0.0.1") || url.starts_with("ws://localhost")) {
        return Err("qa_peer only talks to a local server".into());
    }
    let resume = dir.join("peer.db").is_file();
    std::fs::create_dir_all(&dir)?;
    let (tx, events) = channel::<Value>();
    let sink: EventSink = Arc::new(move |event| {
        let value = serde_json::to_value(event).unwrap();
        if value["type"] == "failed" { println!("event: failed {value}"); } else { println!("event: {}", value["type"]); }
        let _ = tx.send(value);
    });
    let engine = Engine::start(dir.join("peer.db").to_str().unwrap().into(), b"disposable-qa-only".to_vec(), sink)?;
    let submit = |v: Value| engine.submit(serde_json::from_value::<Command>(v).unwrap()).unwrap();
    submit(json!({"type": if resume {"connect"} else {"register"}, "url": url, "handle": null, "invite": null}));
    let own = loop {
        let e = events.recv()?;
        if e["type"] == "authenticated" || e["type"] == "registered" {
            if let Some(device) = e["device"].as_str().or(e["device_id"].as_str()) { break device.to_string(); }
        }
    };
    submit(json!({"type":"profile_get","query":own}));
    let text = |id: String, t: String| format!("\u{2063}OBS1:{}", json!({"v":1,"type":"text","id":id,"text":t}));
    if let Some(target) = args.get(3) {
        // Registration runs in its own session that drops profile commands; retry until stored.
        submit(json!({"type":"profile_set","avatar_mime":"image/png","avatar_base64":AVATAR}));
        loop {
            let Ok(e) = events.recv_timeout(std::time::Duration::from_secs(4)) else {
                submit(json!({"type":"profile_set","avatar_mime":"image/png","avatar_base64":AVATAR}));
                continue;
            };
            if e["type"] == "profile" && e["avatar_base64"].as_str().is_some_and(|v| !v.is_empty()) {
                println!("OWN AVATAR STORED bytes={}", e["avatar_base64"].as_str().unwrap().len());
                break;
            }
        }
        submit(json!({"type":"profile_get","query":target}));
        let device = loop {
            let Ok(e) = events.recv_timeout(std::time::Duration::from_secs(3)) else {
                submit(json!({"type":"profile_get","query":target}));
                continue;
            };
            if e["type"] == "profile" && e["chat_code"] == target.as_str() { break e["device"].as_str().unwrap().to_string(); }
            if e["type"] == "failed" && e["code"] == "profile_not_found" { return Err("target not found".into()); }
        };
        submit(json!({"type":"send","recipient_device":device,"body":text(format!("hello-{}", std::process::id()), "Привет, я написал первым и у меня есть аватар".into())}));
    }
    let mut n = 0;
    loop {
        let e = events.recv()?;
        if e["type"] == "profile" {
            println!("PROFILE device={} own={} code={} avatar_bytes={}", e["device"], own, e["chat_code"], e["avatar_base64"].as_str().map_or(0, str::len));
        }
        if e["type"] == "message" && n < 3 {
            let Some(from) = e["sender_device"].as_str().map(str::to_owned) else { continue };
            if from == own { continue; }
            submit(json!({"type":"directory_set","device":from,"standing":"approved"}));
            n += 1;
            let reply = if n == 1 { "Привет! Это тестовый собеседник. Длинное сообщение, чтобы проверить перенос строк в пузыре и цвет текста в обеих темах.".to_string() } else { format!("Ответ #{n}") };
            submit(json!({"type":"send","recipient_device":from,"body":text(format!("echo-{n}-{}", std::process::id()), reply)}));
        }
    }
}

const AVATAR: &str = "";
